```js
// B-6b LB hop, one implementation for both machines (the stage-2..5 branch
// and the stage-6 chain's s5===2): the real enqueue runs through the LB's
// own selection, then the frame reads the record the LB handed back.
//
// CHECKS: the branch's named counter-examples hold on either machine —
// an all-down pool returns the funnel's refusal record, so the trace is
// stamped `refused` (the walk ends at the refusal hop; no served data) and
// the frame narrates the refusal card, never the record object (no
// "[object Object]"); a one-down pool narrates the seat the cursor crossed
// from lastSkip() (skip narration, not an abort); and a healthy pool keeps
// the clean byte shape ("queued", no skip suffix). TRACE mutates in place —
// the caller owns final-hop selection and the restart path.
export function lbEnqueueHop(trace, { serverAddress, lb, bumpTick, onRefusal }) {
  const atTick = bumpTick();
  const target = lb.enqueue({
    id: `you:${atTick}`,
    from: trace.from,
    to: serverAddress,
    request: trace.request,
    atTick,
    isYou: true,
  });
  if (target?.refused === true) {
    trace.refused = true;
    onRefusal?.(target);
    return { frame: lbRefusedFrame(serverAddress, target, trace.request), refused: true };
  }
  trace.targetServer = target;
  const skippedAt = lb.lastSkip?.();
  return { frame: lbEnqueuedFrame(serverAddress, target, trace.request, skippedAt), refused: false };
}
```

