export function lbRefusedFrame(serverAddress, record, request) {
  return `LB ${serverAddress} -> ${record.to} | ${request} => connection refused (nothing enqueued)`;
}

// DOCUMENTS: the B-6b LB hop itself, one implementation for both machines —
// the stage-2..5 branch in trace.js and the stage-6 chain's s5===2 in
// trace-stage6.js. The real enqueue runs through the LB's own selection
// (health-aware cursor, network delivery), and the returned frame is minted
// from the record the LB handed back. The caller passes its live trace in
// and reads { frame, refused } out — the trace mutates in place; final-hop
// selection and the restart path stay the caller's machine state.
//
// CHECKS: the hop's named counter-examples hold on either machine — an
// all-down pool returns the funnel's refusal record, so the trace is
// stamped `refused` and the frame narrates the refusal card, not the record
// object (no "[object Object]", nothing enqueued); a one-down pool keeps
// the clean "queued" byte shape plus the seat the cursor crossed, named by
// lastSkip(); a healthy pool narrates plain "queued". No probabilities:
// the enqueue really happened, or the refusal record says so.
export function lbEnqueueHop(trace, { serverAddress, lb, bumpTick, onRefusal }) {
  const atTick = bumpTick();
  const target = lb.enqueue({
    id: `you:${atTick}`,
    from: trace.from,
    to: serverAddress,
    request: trace.request,
    atTick,
    isYou: true,
  });
  if (target?.refused === true) {
    trace.refused = true;
    onRefusal?.(target);
    return { frame: lbRefusedFrame(serverAddress, target, trace.request), refused: true };
  }
  trace.targetServer = target;
  const skippedAt = lb.lastSkip?.();
  return {
    frame: lbEnqueuedFrame(serverAddress, target, trace.request, skippedAt),
    refused: false,
  };
}

